func (db *DB) getTotalLimit(pagination *filters.Pagination, ...) (int, error) {
	totalLimit := pagination.Offset + db.getLimit(pagination.Limit)
	if totalLimit == 0 {
		return 0, fmt.Errorf("invalid default limit: %v", ...)
	}
	if !addl.ReferenceQuery && totalLimit > int(db.config.QueryMaximumResults) {
		return 0, fmt.Errorf("query maximum results exceeded: ...")
	}
	return totalLimit, nil
}
